shared_set("started", 0)
let gate := channel()
func factory() {
    mut a := 0
    mut b := 0
    func apply_change(key) {
        if key == 0 { a = 1 }
        if key == 1 { b = 1 }
        if key < 2 { shared_add_int("started", 1) gate.receive() }
        return a + b
    }
    return apply_change
}
let apply_change := factory()
let left := func() { return apply_change(0) }
let right := func() { return apply_change(1) }
let a := spawn_task(left)
let b := spawn_task(right)
while shared_get("started") < 2 {}
gate.send(1)
gate.send(1)
await await_task(a)
await await_task(b)
print(apply_change(2))
